parameters.jsonBody:
={
  "text": "🚨 *CRITICAL EXECUTION FAILURE:* {{ $('Format Error Snapshot').item.json.error_id }} in {{ $('Format Error Snapshot').item.json.workflow_name }}",
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "🚨 CaterFlow Outbound Engine Failure (DLQ)",
        "emoji": true
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Error ID:*\n`{{ $('Format Error Snapshot').item.json.error_id }}`"
        },
        {
          "type": "mrkdwn",
          "text": "*Workflow:*\n{{ $('Format Error Snapshot').item.json.workflow_name }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Failed Node:*\n`{{ $('Format Error Snapshot').item.json.failed_node }}`"
        },
        {
          "type": "mrkdwn",
          "text": "*Timestamp:*\n{{ $('Format Error Snapshot').item.json.timestamp }}"
        }
      ]
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Error Message:*\n```{{ $('Format Error Snapshot').item.json.error_message.slice(0, 400) }}```"
      }
    },
    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "text": {
            "type": "plain_text",
            "text": "🔍 Debug Execution in n8n",
            "emoji": true
          },
          "style": "danger",
          "url": "{{ $('Format Error Snapshot').item.json.execution_url }}"
        }
      ]
    }
  ]
}

={
  "username": "CaterFlow Sentry (DLQ)",
  "avatar_url": "https://img.icons8.com/fluency/96/error.png",
  "embeds": [
    {
      "title": "🚨 CATERFLOW ENGINE FAILURE — DEAD-LETTER QUEUED",
      "color": 15158332,
      "description": "An unhandled error terminated an execution in **{{ $('Format Error Snapshot').item.json.workflow_name }}**.",
      "fields": [
        {
          "name": "Error Tracking ID",
          "value": "`{{ $('Format Error Snapshot').item.json.error_id }}`",
          "inline": true
        },
        {
          "name": "Failed Node",
          "value": "`{{ $('Format Error Snapshot').item.json.failed_node }}`",
          "inline": true
        },
        {
          "name": "Timestamp",
          "value": "{{ $('Format Error Snapshot').item.json.timestamp }}",
          "inline": true
        },
        {
          "name": "Error Diagnostics",
          "value": "```\n{{ $('Format Error Snapshot').item.json.error_message.slice(0, 500) }}\n```"
        },
        {
          "name": "Immediate Action",
          "value": "👉 [Inspect Failed Execution in n8n]({{ $('Format Error Snapshot').item.json.execution_url }})"
        }
      ]
    }
  ]
}
